<?php
namespace App\Http\Controllers;
use App\Http\Requests\StoreTransportPassengerRequest;use App\Models\TransportPassenger;use App\Services\TransportAuditService;
class TransportPassengerController extends Controller {public function index(){return view('transport.passengers.index',['passengers'=>TransportPassenger::forCompany(auth()->user()->company_id)->latest()->paginate(20)]);}public function store(StoreTransportPassengerRequest $r,TransportAuditService $audit){$p=TransportPassenger::create($r->validated()+['company_id'=>$r->user()->company_id,'created_by'=>$r->user()->id]);$audit->record($p->company_id,'transport_passenger_created','passenger',$p->id,$r->user()->id);return back()->with('success','Pasajero registrado.');}public function update(StoreTransportPassengerRequest $r,TransportPassenger $passenger,TransportAuditService $audit){$this->own($passenger);$passenger->update($r->validated()+['updated_by'=>$r->user()->id]);$audit->record($passenger->company_id,'transport_passenger_updated','passenger',$passenger->id,$r->user()->id);return back()->with('success','Pasajero actualizado.');}public function destroy(TransportPassenger $passenger,TransportAuditService $audit){$this->own($passenger);$passenger->update(['status'=>'inactive','updated_by'=>auth()->id()]);$audit->record($passenger->company_id,'transport_passenger_deactivated','passenger',$passenger->id,auth()->id());return back()->with('success','Pasajero desactivado sin eliminar su historial.');}private function own($m):void{abort_unless((int)$m->company_id===(int)auth()->user()->company_id,404);}}
